"""Standalone review artifact with actual run results and all world tables."""
import base64,csv,html,json,statistics,sys,zipfile
from pathlib import Path
root=Path(__file__).resolve().parents[1];output=Path(sys.argv[1] if len(sys.argv)>1 else root.parent/'outputs');output.mkdir(parents=True,exist_ok=True)
w=json.loads((root/'research/world/world.json').read_text());analysis=json.loads((root/'research/world/analysis.json').read_text())
def table(rows):
 if not rows:return '<p>No completed results.</p>'
 cols=list(rows[0]);return '<div class="scroll"><table dir="ltr"><thead><tr>'+''.join('<th>'+html.escape(str(c))+'</th>' for c in cols)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(f'{r.get(c):.5g}' if isinstance(r.get(c),float) else str(r.get(c,'')))+'</td>' for c in cols)+'</tr>' for r in rows)+'</tbody></table></div>'
def pic(path,caption):
 path=Path(path)
 return ('<figure><img alt="'+html.escape(caption)+'" src="data:image/png;base64,'+base64.b64encode(path.read_bytes()).decode()+'"><figcaption>'+html.escape(caption)+'</figcaption></figure>') if path.exists() else '<p>Figure not yet available.</p>'
parts=['''<!doctype html><html lang="he" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Scheduling Simulation — Research review v0.4</title><style>body{font:17px/1.65 Arial,sans-serif;color:#203040;background:#f4f7fa;margin:0}main{max-width:1200px;margin:auto;padding:30px}h1{font-size:34px;line-height:1.3}h2{margin-top:38px}section,.card{background:white;padding:24px;border:1px solid #d7e0e8;border-radius:10px;margin:20px 0}.status{border-right:6px solid #b76b00;background:#fff6df;padding:18px}.scroll{overflow:auto;max-height:600px}table{border-collapse:collapse;width:100%;font:14px/1.5 Arial}th,td{padding:9px;border-bottom:1px solid #dce4ed;text-align:left;vertical-align:top}th{background:#163652;color:white;position:sticky;top:0}tr:nth-child(even){background:#f0f5f8}img{width:100%;height:auto}figcaption{font-size:14px;color:#526579}summary{cursor:pointer;font-weight:bold;padding:12px}code{direction:ltr;unicode-bidi:embed;font-size:15px}a{color:#075e91}@media print{details{display:block}.scroll{max-height:none;overflow:visible}section{break-inside:avoid}}</style><main><h1>Scheduling Simulation<br>מודל מכויל — גרסת מחקר 0.4</h1><p>הפרדת פעולות, משפחות מכונות ומכונות פיזיות; ביקוש חיצוני; תוצאות ניסוי בפועל.</p><div class="status"><b>סטטוס: המימוש נבדק, אך Baseline יציב עדיין לא אושר.</b><br>הדוח אינו מעניק אישור לגרסה על בסיס מעבר בדיקות תוכנה בלבד. בדיקת Replay חזותית לא הושלמה, וחלונות הכיול אינם מוכיחים עדיין התייצבות.</div>''']
parts+=['<section><h2>הממצאים שהובילו למודל</h2>'+table([{'Metric':'Source reports','Value':26222},{'Metric':'Retained jobs / items','Value':'343 / 164'},{'Metric':'Part families / operations','Value':'19 / 86'},{'Metric':'Physical machines / fixed processing entries','Value':'68 / 2,284'},{'Metric':'Quantity mean / median / maximum','Value':'2,397.71 / 475 / 50,300'},{'Metric':'Current joint-capacity candidate jobs/day','Value':w['demand']['baseline_jobs_per_day']}])+'<p>המסלולים והכמויות נגזרו מדיווחים. כמות העבודה היא אומדן מצטבר ולא גודל הזמנת לקוח מאומת. זמני התקן שימשו בסיס הנדסי לזמן מכונה, אך אינם מבודדים בוודאות את הזמן האוטומטי.</p>'+pic(root/'research/world/source_analysis.png','התפלגות הכמויות, ECDF וכיסוי דפוסי מסלול — ללא קיצוץ הזנב')+pic(root/'research/world/processing_source_evidence.png','זמני דיווח ותקן: יש להבחין בינם לבין זמן מכונה אוטומטי')+'</section>']
parts+=['<section><h2>מדוע קצב הבסיס השתנה</h2><p>חישוב לפי מכונות בלבד נתן 2.183 עבודות ביום. אבל העבודה הידנית הנדרשת היא 9,489.54 דקות לעבודה, מול 11,700 דקות עובד זמינות ביום לפני הליכה ושינוע. הקצב הזה מציע כ־177% עומס אנושי. הכמויות לא הוקטנו; מועמד הבסיס החדש, 0.9247 עבודות ביום, נותן 75% עומס ידני מחושב לפני הליכה ושינוע.</p><p>ארבעת עובדי ה־Setup כמעט אינם מנוצלים במועמד הנוכחי; לכן טרם הושג גם היעד של אילוץ Setup משמעותי. אין הצדקה לשנות את מספרם בתוך הריצה כדי להסתיר זאת.</p><p>זהו מועמד לכיול, לא אישור יציבות. הזמנות גדולות ללא פיצול עשויות להימשך חודשים, ולכן יש צורך בהפרדה בין סיום drain לבין התייצבות תוך כדי הגעות.</p></section>']
